#include <iostream>
#include <vector>
#include <queue>
#include <string>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;

struct FlowGraph {
    struct Edge {
        int to, reverse;
        ll capacity;
    };

    vector<vector<Edge>> graph;
    vector<int> level, iter;
    int source, sink;

    FlowGraph(int nodes, int s, int t) : graph(nodes), level(nodes), iter(nodes), source(s), sink(t) {}

    void addEdge(int u, int v, ll cap) {
        graph[u].push_back({v, (int)graph[v].size(), cap});
        graph[v].push_back({u, (int)graph[u].size()-1, 0});
    }

    bool buildLevel() {
        fill(level.begin(), level.end(), -1);
        level[source] = 0;
        queue<int> q;
        q.push(source);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto &e : graph[u]) {
                if (e.capacity > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[sink] != -1;
    }

    ll augment(int u, ll flow) {
        if (u == sink) return flow;
        for (int &i = iter[u]; i < (int)graph[u].size(); ++i) {
            Edge &e = graph[u][i];
            if (e.capacity > 0 && level[e.to] == level[u] + 1) {
                ll pushed = augment(e.to, min(flow, e.capacity));
                if (pushed > 0) {
                    e.capacity -= pushed;
                    graph[e.to][e.reverse].capacity += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll dinic() {
        ll total = 0;
        while (buildLevel()) {
            fill(iter.begin(), iter.end(), 0);
            ll pushed;
            while ((pushed = augment(source, 1e18)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, T;
    cin >> n >> T;

    vector<string> grid(n);
    int zy = -1, zx = -1;
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Z') {
                zy = i; zx = j;
            }
        }
    }

    string dummy;
    getline(cin, dummy);
    getline(cin, dummy);

    vector<string> exits(n);
    for (int i = 0; i < n; ++i) {
        cin >> exits[i];
    }

    vector<vector<int>> dist(n, vector<int>(n, -1));
    queue<pair<int, int>> bfsQ;
    bfsQ.push({zy, zx});
    dist[zy][zx] = 0;

    const int dy[] = {1, -1, 0, 0};
    const int dx[] = {0, 0, 1, -1};

    while (!bfsQ.empty()) {
        auto [y, x] = bfsQ.front(); bfsQ.pop();
        for (int d = 0; d < 4; ++d) {
            int ny = y + dy[d], nx = x + dx[d];
            if (ny < 0 || ny >= n || nx < 0 || nx >= n) continue;
            if (dist[ny][nx] != -1 || grid[ny][nx] == 'Y') continue;
            dist[ny][nx] = dist[y][x] + 1;
            if (dist[ny][nx] < T) {
                bfsQ.push({ny, nx});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                if (dist[i][j] == -1) dist[i][j] = T;
                else dist[i][j] = min(dist[i][j], T);
            }
        }
    }

    vector<vector<int>> nodeId(n, vector<int>(n, -1));
    int nodeCount = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                nodeId[i][j] = nodeCount++;
            }
            if (exits[i][j] >= '1' && exits[i][j] <= '9') {
                nodeId[i][j] = nodeCount++;
            }
        }
    }

    int src = 0, dst = nodeCount + 1;
    FlowGraph flow(nodeCount + 2, src, dst);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                flow.addEdge(src, nodeId[i][j], grid[i][j] - '0');
            }

            if (exits[i][j] >= '1' && exits[i][j] <= '9') {
                flow.addEdge(nodeId[i][j], dst, exits[i][j] - '0');
            }

            for (int d = 0; d < 4; ++d) {
                int ni = i + dy[d], nj = j + dx[d];
                if (ni < 0 || ni >= n || nj < 0 || nj >= n) continue;
                if (grid[ni][nj] == 'Y' || grid[ni][nj] == 'Z') continue;

                if (nodeId[i][j] != -1 && nodeId[ni][nj] != -1) {
                    flow.addEdge(nodeId[i][j], nodeId[ni][nj], 1000000000);
                }
            }
        }
    }

    cout << flow.dinic() << '\n';
    return 0;
}
